function Seo({ title, description, schema }: { title: string; description: string; schema?: Record<string, unknown> }) {
  useEffect(() => {
    document.title = title;
    const setMeta = (name: string, content: string, property = false) => {
      let el = document.head.querySelector(`meta[${property ? 'property' : 'name'}="${name}"]`) as HTMLMetaElement | null;
      if (!el) { el = document.createElement('meta'); el.setAttribute(property ? 'property' : 'name', name); document.head.appendChild(el); }
      el.content = content;
    };
    setMeta('description', description); setMeta('og:title', title, true); setMeta('og:description', description, true); setMeta('og:type', 'website', true); setMeta('twitter:card', 'summary_large_image');
    const canonical = (document.head.querySelector('link[rel="canonical"]') || document.head.appendChild(document.createElement('link'))) as HTMLLinkElement;
    canonical.rel = 'canonical'; canonical.href = window.location.origin + window.location.pathname;
    let jsonLd = document.head.querySelector('#teko-jsonld') as HTMLScriptElement | null;
    if (!jsonLd) { jsonLd = document.createElement('script'); jsonLd.id = 'teko-jsonld'; jsonLd.type = 'application/ld+json'; document.head.appendChild(jsonLd); }
    jsonLd.textContent = JSON.stringify(schema || { '@context': 'https://schema.org', '@type': 'Organization', name: 'TEKO EV', url: window.location.origin, description });
  }, [title, description, schema]);
  return null;
}

